const assert = require('assert');
const LinkedList = require('./linked_list');

// push + toArray
const ll = new LinkedList();
ll.push(1);
ll.push(2);
ll.push(3);
assert.deepStrictEqual(ll.toArray(), [1, 2, 3], 'toArray after push');
assert.strictEqual(ll.size(), 3, 'size should be 3');

// peek
assert.strictEqual(ll.peek(), 3, 'peek returns last');
assert.strictEqual(ll.size(), 3, 'peek does not remove');

// pop
assert.strictEqual(ll.pop(), 3, 'pop returns last');
assert.strictEqual(ll.size(), 2, 'size after pop');
assert.deepStrictEqual(ll.toArray(), [1, 2], 'toArray after pop');

// pop until empty
ll.pop();
ll.pop();
assert.strictEqual(ll.size(), 0, 'empty after all pops');

// empty throws
try {
  ll.pop();
  assert.fail('should throw on empty pop');
} catch (e) {
  assert.ok(e.message !== 'should throw on empty pop', 'pop threw correctly');
}
try {
  ll.peek();
  assert.fail('should throw on empty peek');
} catch (e) {
  assert.ok(e.message !== 'should throw on empty peek', 'peek threw correctly');
}

console.log('All tests passed!');
